fn ensure_desktop_main(webview: &Webview) -> Result<(), SshForwardCommandError> {
    ensure_main_window(webview.label())
        .map_err(|_| super::error::SshForwardErrorCode::DesktopInstanceMismatch.command_error())
}

#[command]
