        if self
            .active_scope
            .lock()
            .await
            .as_ref()
            .is_some_and(|active| active.id == input.scope_id)
        {
            return Err(SshForwardErrorCode::ScopeActive.command_error());
        }
        let purged = match self.store.existing_scope(&input.scope_id) {
            Ok(store) => store
                .purge_if_deleted(&input.known_scopes)
